def unique_wraparound_substrings(s):
    longest = [0]*26
    run = 0
    for i,char in enumerate(s):
        run = run+1 if i and (ord(char)-ord(s[i-1]))%26==1 else 1
        index = ord(char)-97
        longest[index] = max(longest[index],run)
    return sum(longest)

